mapper.select:
SELECT fcm_token, noti_payment, noti_quest, noti_finance, noti_allowance
FROM T_MBR_INFO_M
WHERE id = #{memberId}

mapper.update:
UPDATE T_MBR_INFO_M
SET fcm_token = IF(id = #{memberId}, #{fcmToken,jdbcType=VARCHAR}, NULL)
WHERE id = #{memberId}
   OR fcm_token = #{fcmToken,jdbcType=VARCHAR}

UPDATE T_MBR_INFO_M
SET noti_payment = #{setting.notificationPayment},
    noti_quest = #{setting.notificationQuest},
    noti_finance = #{setting.notificationFinance}
WHERE id = #{memberId}
